function decode(body) {
  return Uint8Array.from(atob(body), (character) => character.charCodeAt(0));
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let pathname;
    try {
      pathname = decodeURIComponent(url.pathname);
    } catch {
      return new Response("Bad request", { status: 400 });
    }

    let asset = ASSETS[pathname];
    if (!asset && pathname.endsWith("/")) asset = ASSETS[pathname + "index.html"];
    if (!asset && !pathname.split("/").pop().includes(".")) asset = ASSETS["/index.html"];

    if (!asset) return new Response("Not found", { status: 404 });

    const immutable = pathname.startsWith("/assets/");
    return new Response(request.method === "HEAD" ? null : decode(asset.body), {
      headers: {
        "Content-Type": asset.contentType,
        "Cache-Control": immutable ? "public, max-age=31536000, immutable" : "public, max-age=0, must-revalidate",
        "X-Content-Type-Options": "nosniff",
      },
    });
  },
};
